PROCEDURE AddTenByValue(BYVAL X : INTEGER)
  X <- X + 10
  OUTPUT "Inside procedure (by value), X = ", X
ENDPROCEDURE

PROCEDURE AddTenByReference(BYREF X : INTEGER)
  X <- X + 10
  OUTPUT "Inside procedure (by reference), X = ", X
ENDPROCEDURE

-- Call 1: by value --
DECLARE Number : INTEGER
Number <- 5
OUTPUT "Before call, Number = ", Number        // Before call, Number = 5
CALL AddTenByValue(Number)
// Inside AddTenByValue: X receives a COPY of Number's value, 5
//   X <- X + 10  =>  X becomes 15 (only the copy changes)
// OUTPUT inside procedure: "Inside procedure (by value), X = 15"
// Procedure ends; the copy X is discarded, Number itself was never touched
OUTPUT "After call, Number = ", Number         // After call, Number = 5  (UNCHANGED)

-- Call 2: by reference --
Number <- 5
OUTPUT "Before call, Number = ", Number        // Before call, Number = 5
CALL AddTenByReference(Number)
// Inside AddTenByReference: X IS Number itself, not a copy
//   X <- X + 10  =>  Number becomes 15 directly, because X and Number are the same variable
// OUTPUT inside procedure: "Inside procedure (by reference), X = 15"
// Procedure ends; Number remains changed, since X was never a separate copy
OUTPUT "After call, Number = ", Number         // After call, Number = 15  (CHANGED)

-- Summary of the trace --
// Both procedures print X = 15 from inside themselves: the +10 happens identically
// either way. The difference is entirely in what Number equals back in the caller
// AFTER the call returns: still 5 after AddTenByValue (a copy was changed, not
// Number), but 15 after AddTenByReference (Number itself was changed).
